767  /// translateOperand - Translates an operand stored in an internal instruction
   768  ///   to LLVM's format and appends it to an MCInst.
   769  ///
   770  /// @param mcInst       - The MCInst to append to.
   771  /// @param operand      - The operand, as stored in the descriptor table.
   772  /// @param insn         - The internal instruction.
   773  /// @return             - false on success; true otherwise.
   774  static bool translateOperand(MCInst *mcInst, const OperandSpecifier *operand, InternalInstruction *insn)
   775  {
   776          switch (operand->encoding) {
   777                  case ENCODING_REG:
   778                          translateRegister(mcInst, insn->reg);
   779                          return false;
   780                  case ENCODING_WRITEMASK:
   781                          return translateMaskRegister(mcInst, insn->writemask);
   782                  CASE_ENCODING_RM:
   783                  CASE_ENCODING_VSIB:
   784                          return translateRM(mcInst, operand, insn);
   785                  case ENCODING_IB:
   786                  case ENCODING_IW:
   787                  case ENCODING_ID:
   788                  case ENCODING_IO:
   789                  case ENCODING_Iv:
   790                  case ENCODING_Ia:
   791                          translateImmediate(mcInst, insn->immediates[insn->numImmediatesTranslated++], operand, insn);
   792                          return false;
   793                  case ENCODING_IRC:
   794                          MCOperand_CreateImm0(mcInst, insn->RC);
   795                          return false;
   796                  case ENCODING_SI:
   797                          return translateSrcIndex(mcInst, insn);
   798                  case ENCODING_DI:
   799                          return translateDstIndex(mcInst, insn);
   800                  case ENCODING_RB:
   801                  case ENCODING_RW:
   802                  case ENCODING_RD:
   803                  case ENCODING_RO:
   804                  case ENCODING_Rv:
   805                          translateRegister(mcInst, insn->opcodeRegister);
   806                          return false;
   807                  case ENCODING_FP:
   808                          translateFPRegister(mcInst, insn->modRM & 7);
   809                          return false;
   810                  case ENCODING_VVVV:
   811                          translateRegister(mcInst, insn->vvvv);
   812                          return false;
   813                  case ENCODING_DUP:
   814                          return translateOperand(mcInst, &insn->operands[operand->type - TYPE_DUP0], insn);
   815                  default:
   816                          //debug("Unhandled operand encoding during translation");
   817                          return true;
   818          }
   819  }
